        sta key_scan_mode
        jsr scan_keyboard
        lda key_ready
        beq check_demo_abort_done
        lda #$00
        sta key_ready
        lda key_code
        cmp #$04                        ; F1
        bne check_demo_abort_done
demo_abort_to_title
        jsr wait_fire_released          ; wait until fire is released
        lda #$06
        sta frame_countdown
demo_abort_wait
        lda frame_countdown
        bne demo_abort_wait
        jmp restart_to_title
check_demo_abort_done
        rts
; Main loop: count down the pause debounce. pause_state bit 7 = paused, bits 0-2 = debounce count (6 after a
; change). Each call lowers the count (6 -> 5 -> 3 -> 1 -> 0) and sets last_game_key to $FF while it runs.
pause_debounce
