        pha
        and #$80
        sta pause_state
        pla
        and #$06                        ; debounce bits 1-2
        beq pause_debounce_done
        sec
        sbc #$01
        ora pause_state
        sta pause_state
        lda #$ff
        sta last_game_key
pause_debounce_done
        rts
; Main loop: while paused and not debouncing, fire on the joystick of the current player ends the pause.
check_pause_fire
