        and #$06
        bne check_pause_fire_done
        lda pause_state
        bpl check_pause_fire_done
        lda current_player              ; player 1 -> CIAPRB (port 1), player 2 -> CIAPRA (port 2)
        eor #$01
        and #$01
        tax
        lda CIAPRA,x
        and #$10
        bne check_pause_fire_done
